    "help.raid.overview.title": "三支隊伍的聯合作戰",
    "help.raid.overview.body": "左翼、中路、右翼三個編隊共同對抗一個首領。擊敗該章的地獄難度章節首領後，即可用自己的編隊進行練習。每個編隊需要三名不同的英雄，正在遠征或探索的編隊無法使用。<br><br>出戰瞬間會複製現有的裝備、技能、陣型與戰術。治療、增益與光環只作用於各自的編隊，施加在首領身上的減益則對所有編隊共同生效。即使一個編隊倒下，其餘編隊也會繼續戰鬥。",
    "help.raid.patterns.title": "攻擊預警與施法打斷",
    "help.raid.patterns.body": "首領下方會顯示攻擊名稱、目標編隊與剩餘時間，將要受擊的編隊邊框也會亮起。鐵錘會優先攻擊目標編隊的前排，橫掃與範圍攻擊會對該編隊全員造成傷害。標記與嘲諷也只在指定編隊內生效。<br><br>出現施法打斷槽的重擊，可以在預警期間削減首領生命來打斷。成功後會出現弱點暴露時間；失敗則所有編隊都會受到一次強力攻擊。首領生命降低後會進入更高階段，攻擊變得更快、更強。預定的招式不會被普通的行動僵直取消。",
    "help.raid.trial.title": "戰鬥練習的範圍",
    "help.raid.trial.body": "目前這是沒有獎勵的戰鬥練習。訓練編隊提供九名示範英雄，任何人都可以體驗。你的編隊也以快照形式參戰，不會消耗或改變英雄、裝備、庫存與進度記錄。本次練習不使用藥水。<br><br>離開標籤頁或視窗被隱藏時，練習計時會暫停。回來後會繼續同一場戰鬥，重新整理頁面則會重置。可以在結果中檢視傷害、治療、存活與施法打斷，並再次挑戰。正式獎勵、重複挑戰與追加怪物尚未確定。",
