    "ng.note": "初始隊伍為<b>稀有1 + 魔法1 + 普通1</b>——從第一個畫面起，英雄名冊就能看出<b>層次</b>。15名唯一英雄是固定名單，不會在開局消耗<br>基礎屬性按各軸分別擲骰，但<b>總和落在稀有度決定的區間</b>內（各稀有度的區間<b>可能重疊</b>）——三張卡的差異有數量與<b>形狀</b>兩方面：稀有 · 普通分佈均勻，魔法則<b>可能在某一軸上大幅突出</b>。裝備和升級都不會提高屬性，所以這裡擲出的數值<b>伴隨一生</b><br><b>稀有度的差距會持續到最後</b>——上限對所有英雄相同，但升級不會提高屬性，所以<b>擲出的形狀就是該英雄的終點</b><br>主罪宗決定罪宗專精（標籤1）與派遣適性——裝備契合（套裝點數）<b>已廢棄</b>——移至隊伍戰術<br>重擲<b>無限且免費</b>——不讓開局選擇變成賭博<br><b>未確定</b>：稀有度區間 · 分佈形狀 · 出現比重（均為提案值）· 特性效果（只擲出名稱）· 職業對主力軸的偏向強度 · 是否允許罪宗 · 職業重複",
