    "pro.begin": "開始",
    "pro.s1.h": "王座",
    "pro.s1.b": "地獄曾有一位王。他便是大惡魔巴爾。\n\n這片土地上的一切都屬於他。\n巴爾將自己的七種情感分給了部下。\n憤怒、嫉妒、貪婪、怠惰、暴食、色慾、傲慢。\n\n王座之下，七名部下等候他的命令。",
    "pro.s2.h": "背叛之夜",
    "pro.s2.b": "在一個格外漆黑的夜晚，七把刀刺進了巴爾的後背。\n\n他回過頭，看見一張張熟悉的面孔。\n他想還擊，力量卻早已被奪走。\n\n有人交出了鑰匙。巴爾被逼得連連後退。腳下的地面塌了。\n王座、俯視他的那些臉，還有地獄的紅光，都在他上方漸漸遠去。",
    "pro.s3.h": "墜落",
    "pro.s3.b": "回頭時看見的面孔一張張模糊了。\n就連那些刀是不是真有七把，他都說不準。\n\n灼燒般的劇痛襲來。巴爾身上正被刻下一道烙印。\n\n要再戰一場，他就得找到肯聽他號令、為他舉刀的人。\n\n<em>那些在我背後捅刀的傢伙，我要一個個找出來。</em>",
    "pro.s4.h": "村莊",
    "pro.s4.b": "他睜開眼時，一個年邁的人類正往他嘴裡喂水。\n如今巴爾成了人，連自己抬起頭都做不到。\n\n一連幾天，村民們都從自己的麵包上掰下一塊餵給他。\n\n<em>這些東西為什麼要救我？</em>",
    "pro.s5.h": "烈焰",
    "pro.s5.b": "村裡燃起了大火。撒旦的大軍來了。\n那個被巴爾逐出地獄的傢伙一路追到了這裡。\n\n巴爾朝他在村中召集的傭兵舉起了手。",
    "pro.s5.q": "“開路。我們去找撒旦。”",
    "pro.end": "第1章 · 憤怒 / 燃燒戰場",
