    "exp.repeat.tip": "開啟後在此區域的關卡間輪流戰鬥 · 關閉後每次勝利都前進到下一關",
    "exp.repeat.sub": "遠征<b>不會自行停止</b>——一場結束後，下一場很快就會出發，停止的方法只有<b>撤退</b>與<b>關閉遊戲</b>兩種 · <b>僅在遊戲開啟期間</b>執行<br>勝利則前進到下一關 · 失敗（全員倒下 · 超時）則重打同一關 · 敗給章節首領則退回前一關 · <b>開啟自動迴圈</b>時在該區域的關卡 I → II → III → I 間輪轉，<b>關閉</b>時按順序前進到下一關（下一關未解鎖則重打同一關 · 擊敗開啟下一難度的首領後進入下一難度的1-1）· 每關都是新的一場，全員恢復後出發",
