    "mm.tut": "新手教學",
    "mm.tut.c1_depart.tab": "在遠征中，你可以派出編隊前往各地戰鬥。戰鬥自動進行，找到的裝備和材料會放入揹包。",
    "mm.tut.c1_depart.place": "先選一個戰鬥地點。每個地點都有相連的關卡，獲勝就能進入下一關，最後一關有該地點的首領。",
    "mm.tut.c1_depart.send": "派出編隊後，英雄會自動戰鬥。遠征只在遊戲開啟時推進。關閉遊戲期間，研究所仍會工作。",
    "mm.tut.c1_storage.tab": "在建設頁可以花費金幣建造建築。每建好一座建築，都會解鎖新的功能。",
    "mm.tut.c1_storage.lot": "選中建築即可在右側檢視它能解鎖哪些功能。建造倉庫會解鎖研究所的資源線。",
    "mm.tut.c1_storage.build": "建造倉庫即可解鎖研究所的資源線，關閉遊戲後也能繼續收集材料。支付費用後，倉庫立即建成。",
    "mm.tut.c1_reg.tab": "關閉遊戲後，研究所也會繼續工作。每條線都要派駐至少一名英雄才會開始運作。",
    "mm.tut.c1_reg.line": "點選空欄位，選擇要派駐到資源線的英雄。",
    "mm.tut.c1_reg.hero": "派駐的英雄仍可參加遠征。派駐的英雄越多，資源線收集材料就越快。",
    "mm.tut.c1_reg.apply": "點選應用，英雄就會進駐，產線隨即開始運作。下次回來時，離線期間收集的材料已存入庫存。",
