    "ch.salvageHint": "右鍵點選裝備並按[鎖定]，即可鎖定或解鎖。鎖定的裝備不會被分解。按[分解]會開啟分解箱。點選裝備放入箱中，或在稀有度 · 等級 · 基底列中挑選，符合的裝備會立即放入箱中；用[執行分解]獲得粉塵後，篩選會被清除。同時選擇多列時，只有符合所有列的裝備才會放入，因此基底詞綴高的裝備可以借基底列保留下來。[自動分解]按小隊分別設定。為每個稀有度 × 部位格選擇保留 · 基底 · 分解；開啟等級條件後，會分解遠低於小隊最低英雄等級的裝備。須同時滿足等級條件與該格設定才會保留；[基底]格只保留基底詞綴達到該部位門檻以上的裝備。暗金 · 手工裝備始終保留。只對新獲得的裝備生效，已持有的裝備需點選[立即應用於揹包]才會分解。將當前規則儲存為預設後，可在其他小隊讀取",
