    "cs.help": "試煉之塔從第一層開始。擊敗已開放的最高層即可解鎖下一層。挑戰失敗也會保留進度，已通關的樓層可以再次挑戰。<br>每層對手固定。你將先對戰精英怪群和關卡首領，再與對手英雄隊伍和章節首領交鋒。層數決定敵人的基礎等級。",
