    "ar.last.rated": "上次決鬥：{result} · 積分{after}（{delta}）",
    "ar.rules": "決鬥規則",
    "ar.help.rating": "決鬥場以積分進行較量。獲勝積分上升，失敗積分下降；擊敗的對手越強上升越多，輸給的對手越強下降越少。積分越過門檻後段位提升。<br>對手候選會均勻分佈在你的積分之下、相近與之上。卡片上的 + / − 是勝負時積分的變化量。決鬥結束後會出現新的候選。<br>積分在決鬥開始的瞬間就已確定——關閉觀戰也不會改變結果。對手是報名了防守編隊的其他玩家。",
