    "ar.last": "上次決鬥：{result} · {sec}秒",
    "ar.help": "選擇已儲存的編隊後，該編隊的英雄與前排 · 後排會原樣出戰。人數與陣型在編隊標籤頁中修改。需滿3名英雄才能開始決鬥。<br>以個人屬性 · 裝備 · 技能，加上所選編隊的隊伍戰術 · 藥水與我方的圖鑑加成，進行單場戰鬥。對手也會使用自己的隊伍戰術 · 藥水。超過時間限制即為平局。<br>決鬥獨立於遠征，沒有獎勵 · 圖鑑擊殺 · 資源消耗。喝下的藥水也不會從庫存中扣除。決鬥場積分與試煉之塔已登上的樓層會被儲存，所選對手與上次結果會在重新進入遊戲後重置。",
