    "dp.help": "線<b>需要派駐英雄</b>才會隨時間生產——遊戲關閉期間也一樣（最多{h}小時 · 搜尋則直到等候位填滿）<br>選擇節點進行<b>研究</b>即可提升等級——需要花費時間，整個研究所<b>同時只能進行一項</b> · 中止可全額返還費用 · 研究所升階會開啟新節點<br>將英雄<b>派駐</b>到線上後，資源 · 賭坊<b>每名英雄產出一份</b>（1名100% · 2名200% · 3名300%），搜尋則<b>每名英雄各跑一個計時器</b>，屬性還會額外加成——幸運：大豐收 · 智力：研究時間 · 魅力：品質 · 體力：熟練（派駐越久越高）· 統率：同線同伴 · 敏捷：研究費用。派駐可與遠征 · 探索兼任<br><b>訓練</b>線讓派駐的英雄獲得經驗（最高至名冊中的最高等級）· <b>賭坊</b>線在酒館的賭坊開放時一同開放",
