    "gb.help": "由酒館開放。沒有次數限制——只要付得起賭注就能轉。“連轉{n}次”會一次轉{n}次，途中賭注不足則就此停止<br>下注後轉動，橫向 · 斜向共{lines}條線上出現三個相同符號即可獲得金幣或材料。百搭可替代其他符號 · 硬幣會截斷線<br>出現{trig}個以上硬幣即觸發鎖定重轉——硬幣固定在原位，每出現一枚新硬幣，重轉次數就恢復為{re}次。盤面填滿即為鉅獎<br>賭注隨當前進行的章而定。更高檔的賭注由酒館升階開啟。不會出現裝備 · 烙印",
