    "exp.cantDepart": "此編隊無法出發",
    "exp.party.note": "一場結束後，損失的生命與<b>倒下狀態都會免費 · 立即恢復</b>——代價是<b>該場的隊伍變薄</b><br>隊伍增益是技能效果而非屬性——統率沒有戰鬥係數",
    "exp.bench.h": "替補",
    "exp.bench.note": "<b>建設不是派遣</b>——它是無需派出英雄即可推進的獨立系統，因此歸建設標籤頁管理<br>派出的英雄不會被鎖定——隨時可以召回，並<b>按經過的時間比例獲得</b>",
    "exp.commission.h": "委託",
    "exp.commission.note": "委託是<b>接下後擱著的目標</b>——不會開啟戰場。從委託板上挑選並接下後，它會<b>疊加在平常的活動之上</b>自動推進<br>每張卡片由<b>一種罪宗</b>決定任務——憤怒：擊殺（怪物 · 精英 · 首領）· 嫉妒：閱讀技能書 · 僱傭英雄 · 貪婪：分解 · 獲得裝備 · 怠惰：材料獲取 · 暴食：強化 · 製作。<b>能夠進行該活動後</b>，該罪宗的卡片就會混入<br><b>材料獲取在離線時也會推進</b>——由研究所的生產填充。既沒有需要另外派出的隊伍，也沒有委託專屬的戰場<br>稀有度分為<b>普通 · 魔法 · 稀有</b>——稀有度越高，目標越窄（一章 · 一個區域 · 一個類別），出現越少，金幣越多。目標只會來自當前能去的地方<br><b>接受即消耗該卡片</b>——接下的卡片會在原位變為進行中，可同時接取的數量是固定的。因此“接哪個委託”就成了一個決策<br>只計算<b>接受之後</b>發生的事——勝利回合中的擊殺 · 手動或自動分解進行的分解（不含揹包滿而熔掉的）· 從分解與研究所獲得的材料 · 強化嘗試（含失敗）· 製作 · 閱讀技能書 · 僱傭英雄 · 勝利回合中獲得的裝備 · 所有小隊共同推進 · <b>沒有期限</b><br>每次[領取]，圖鑑中該<b>罪宗格</b>的領取次數就會累加一次<br>完成後用<b>[領取]</b>獲得金幣 · <b>[放棄]</b>沒有懲罰（只捨棄進度）——空出的位置會出現新卡片<br><b>委託等級</b>——透過研究研究所搜尋線的<b>委託</b>節點提升（研究下一級需要完成規定次數的委託）。等級提升後，<b>新出現的卡片</b>的目標與金幣會一同增加，且金幣增幅更大——研究完成的瞬間，所有未接受的卡片都會按新等級重新出現，已接受的委託則保留進度",
