    "tc.name.guardian": "守護者",
    "tc.desc.guardian": "我方領袖是前排唯一存活的我方英雄時，我方後排受到的傷害降低 {p1}。",
    "tc.name.unity": "眾志成城",
    "tc.desc.unity": "至少有 {p2} 名我方英雄存活時，我方英雄的直接傷害提高 {p1}。",
    "tc.name.dying_curse": "臨終詛咒",
    "tc.desc.dying_curse": "每當一名我方英雄倒下，敵方目前為正的防禦力及各項元素抗性降低 {p1}，每回合最多疊加 {p2} 次。",
    "tc.name.giant": "巨人",
    "tc.name.desperate_charge": "決死衝鋒",
    "tc.name.mutual_cover": "盾陣",
    "tc.desc.mutual_cover": "部署為前排兩人、後排一人時，一名前排英雄受到傷害，另一名前排英雄會代其承受其中的 {p1}。",
    "tc.name.open_order": "散開陣形",
    "tc.name.iron_line": "背水陣",
    "tc.desc.iron_line": "出戰英雄全數部署於前排時，首名受到致命傷害的友方英雄會保留 1 點生命。每場戰鬥觸發一次。",
    "tc.name.pursuit": "追擊陣",
    "tc.desc.pursuit": "全員部署於前排時，單體攻擊優先選擇可攻擊目標中剩餘生命比例最低的敵人。",
    "tc.name.hammer_anvil": "鶴翼陣",
    "tc.desc.hammer_anvil": "部署為前排兩人、後排一人時，敵方前排單位所受傷害的 {p1} 由敵方後排單位平攤。",
    "tc.name.field_medics": "後方醫療隊",
    "tc.desc.field_medics": "部署為前排兩人、後排一人時，兩名前排英雄受到的治療量提高 {p1}。",
    "tc.name.vanguard_barrier": "先鋒壁壘",
    "tc.desc.vanguard_barrier": "部署為前排一人、後排兩人時，每回合開始，前排英雄獲得相當於自身最大生命值 {p1} 的護盾。",
    "tc.name.aimed_fire": "精準射擊",
    "tc.desc.aimed_fire": "部署為前排一人、後排兩人時，兩名後排英雄的單體攻擊暴擊率額外增加 {p1}。",
    "tc.name.volley": "集中火力",
    "tc.desc.volley": "出戰英雄全數部署於後排時，對敵方前排單位造成的傷害提高 {p1}。",
    "tc.name.rapid_deployment": "快速展開",
    "tc.desc.rapid_deployment": "出戰英雄全數部署於後排時，每回合開始，各英雄的行動條增加 {p1}。",
    "tc.desc.open_order": "出戰英雄全數部署於後排時，受到的範圍攻擊傷害降低 {p1}。",
    "tc.desc.desperate_charge": "出戰英雄全數部署於前排時，整場戰鬥對敵人造成的傷害提高 {p1}。",
    "tc.desc.giant": "我方僅剩一名英雄存活時，其七項基本屬性提高 {p1}。",
    "tc.name.baggage": "輜重隊",
    "tc.desc.duel": "我方隊長的單體攻擊只以敵方隊長為目標。敵方隊長倒下後，按常規規則選擇目標。",
    "tc.desc.wedge": "我方隊長的單體攻擊命中後，會標記目標 {p1} 秒。隊友的單體攻擊優先攻擊被標記的敵人。",
    "tc.desc.trojan": "每回合開始後的 {p1} 秒內，我方後排無法行動。此後，我方後排的單體攻擊優先瞄準敵方後排。",
    "tc.desc.charge": "每回合開始時，我方前排立即行動，後排的首次行動延後 {p1} 秒。",
    "tc.desc.shieldwall": "我方後排受到直擊傷害時，由存活的前排隊友分攤其中的 {p1}。",
    "tc.desc.guard": "我方隊長受到單體直擊傷害時，由當前生命值最高的隊友代為承受其中的 {p1}。",
    "tc.desc.turtle": "每回合開始後的 {p1} 秒內，我方所受傷害降低 {p2}，攻擊速度降低 {p3}。",
    "tc.desc.retreat": "每回閤中，我方前排英雄的生命值比例首次低於 {p1} 時，會尋找剩餘生命值比例最高的後排隊友。若該隊友的生命值比例更高，雙方便交換位置，回合結束後歸位。",
    "tc.desc.poison_arrow": "將我方物理傷害的 {p1} 轉化為毒素傷害。",
    "tc.desc.fire_arrow": "將我方物理傷害的 {p1} 轉化為火焰傷害，並有 {p2} 機率使目標燃燒。",
    "tc.desc.baggage": "我方英雄喝下藥水時，其他存活的隊友平分相當於其治療量 {p1} 的治療。",
