    "sk.cool": "冷卻{s}秒",
    "sk.cdrShort": "冷卻縮減",
    "sk.slots.note": "輪到行動時：<b>等待最久的技能</b> → 若並列則按<b>格位順序</b> → 都沒有則普通攻擊。<b>魔法武器沒有普通攻擊</b>——沒有準備好的技能時，行動槽會保持滿格等待，技能一準備好就立即施放<br>每次行動只用一個。技能會<b>取代</b>該次行動的攻擊，且沒有法力——行動1次就是唯一的消耗<br>冷卻按實時流逝<br>普通攻擊始終是<b>物理</b>——元素傷害只來自技能<br>技能<b>歸屬於職業</b>——一個技能只屬於一個職業，英雄欄來自<b>英雄的職業池</b>，習得欄來自<b>學過的書</b>。<b>打擊、治療、召喚</b>技能無論在哪一格，都必須手持該技能所屬職業的武器才會施放；戰吼、光環、祝福等<b>增益、減益</b>不看武器<br>⚠ 名稱與形態已確定，但<b>倍率、攻擊次數、冷卻、持續時間尚未釋出</b>——當前數值是臨時的",
    "sk.sinTree": "{sin}專精",
    "sk.sinTree.sub": "所有{sin}英雄共享",
    "sk.sinTree.missing": "<b>最下一行（反應型）在設計上只定了方向</b>——“當……時產生……效果”的威力取決於觸發頻率，還沒有衡量其數值的標準。",
    "sk.mastery": "{cls}專精",
    "sk.mastery.missing": "與罪宗專精<b>結構相同</b>。<b>最上一行3格按職業已確定</b>。<br><b>其下3格的效果由穿戴的裝備開啟。</b>快速武器開啟傷害%，慢速武器開啟攻擊速度，本職業的鎧甲類別開啟鎧甲專精。裝備不匹配時也能先投階，但效果處於關閉狀態。<br>最下一行的反應型節點仍在設計中。",
    "sk.advTree": "轉職專精",
