    "sk.adv.lineNeed": "習得轉職技能",
    "sk.adv.band.common": "通用專精",
    "sk.advTree.missing": "轉職後用<b>1點共用技能點</b>學習所選路線的三個主技能之一。技能點每級獲得，與罪宗、職業專精共用。<br>只有主技能階段在英雄Lv30、35、40、45、50時依次開啟Lv1、2、3、4、5。特殊、變體、必殺技分支目前準備中。",
    "sk.lockedSuffix": "（未解鎖）",
    "sk.grid.note": "專精不是分叉的技能樹，而是<b>自上而下疊加</b>的結構——<b>上行先開啟，越往下開啟越晚</b><br>點選格子提升1階。尚無法開啟的格會標出<b>所需等級</b>。<b>空位是尚未設計的位置</b>，保留虛線框是為了顯示最多能走到哪裡",
    "tv.h": "僱傭英雄",
    "tv.sub": "稀有層——職業×罪宗×初始特性在登場時隨機",
    "tv.reroll.note": "酒館重新整理=<b>英雄版的物品刷取</b>——隨機迴圈位於<b>稀有層</b>。罪宗×職業的35格全部由這裡供應",
    "tv.tiers.note": "<b>唯一</b>——名稱、職業、罪宗固定+固有技能1個（英雄專屬），英雄名冊中只能有1名。本篇上限15名（每職業3名）<br><b>稀有</b>——全部隨機，固有技能從通用池中分配。專門負責覆蓋罪宗×職業的35格",
