    "cx.note": "每當從該怪物收集的圖鑑經驗越過累計門檻，<b>該怪物的圖鑑等級</b>就會提升，並逐個開啟獎勵效果——前幾個階段（擊殺經驗、對其傷害、掉落機率）<b>只對該怪物</b>生效 · 最後一個階段則使<b>該怪物的一條戰鬥詞綴常駐於隊伍全員</b>——<b>刷怪推動圖鑑</b><br>每次擊殺的圖鑑經驗由該次遠征的難度決定——難度越高積累越快 · 只計算獲勝回合中的擊殺 · 按首領級別區分的差異留待後續<br>滑鼠懸停在卡片上，會顯示該怪物的故事與等級階段",
