    "bt.note": "可以觀戰，但<b>並非必須</b>——倍速只改變進行速度。遠征中更換的裝備、技能樹在首領戰中也會<b>立即</b>生效 · <b>贏下回合的那一刻即獲得該回合獎勵</b>（揹包、金幣、經驗、圖鑑）。<br><b>撤退</b>會停止遠征——進行中的回合作廢，已獲勝回合的獎勵保留 · 若在一場結束、正倒數下一場時按下，下一場便不會出發。關閉遊戲時，遠征也會就地中斷。",
