    "화상 걸린 적에게 주는 데미지\tDamage to Burned enemies": "對燃燒敵人的傷害",
    "냉기 스킬 쿨타임 감소\tCold skill cooldown reduction": "冰霜技能冷卻縮減",
    "내가 건 결빙 세기\tFreeze strength": "施加的凍結強度",
    "번개 관통\tLightning Penetration": "閃電穿透",
    "번개 스킬이 터질 확률\tLightning skill burst chance": "閃電技能爆發機率",
    "공격 속도\tAttack Speed": "攻擊速度",
