    "스킬 쿨타임 감소\tSkill cooldown reduction": "技能冷卻縮減",
    "스킬 데미지\tSkill Damage": "技能傷害",
    "스킬이 맞힌 적 하나마다 그 스킬 데미지\tSkill damage per enemy hit": "技能每命中一名敵人，該技能傷害",
    "받는 피해 감소\tDamage Reduction": "傷害減免",
