    "전열에 혼자 서면 받는 피해 감소\tDamage reduction when alone in front": "獨自站在前排時傷害減免",
    "오오라 효과\tAura effect": "光環效果",
    "최종 데미지\tFinal Damage": "最終傷害",
    "타격의 일부가 고정 피해로\tPart of each hit becomes fixed damage": "部分打擊轉為真實傷害",
    "모으기 속도\tCharge speed": "蓄力速度",
    "체력이 가득 찬 적에게 주는 첫 타격 데미지\tFirst-hit damage to full-HP enemies": "對生命全滿敵人的首擊傷害",
    "평타가 한 발 더 나갈 확률\tChance for an extra basic attack": "普攻額外射出一發的機率",
    "파티의 평타 덤 데미지\tParty on-hit effect damage": "隊伍普攻附加傷害",
    "적이 쓰러질 때마다 파티 공격 속도(3초)\tParty Attack Speed for 3s on each kill": "每當敵人倒下，隊伍攻擊速度（3秒）",
    "내 회복량\tHealing done": "造成的治療量",
    "축복 효과\tBlessing effect": "祝福效果",
    "넘친 회복이 보호막으로\tOverhealing becomes a shield": "溢位治療轉為護盾",
    "내 디버프 효과\tDebuff effect": "施加的減益效果",
