    "적에게 걸린 버프 하나마다 그 적에게 주는 데미지\tDamage per buff on the enemy": "敵人每有一個增益，對其造成的傷害",
    "물리 피해\tPhysical Damage": "物理傷害",
    "받은 피해의 일부만큼 다음 공격 데미지\tDamage taken adds to your next attack": "受到傷害的一部分加到下次攻擊",
