    "터지는 데미지 증가\tMore burst damage": "爆發傷害提高",
    "터질 때 같은 줄 적에게 {v}로 번진다\tBursts spread to the same row at {v}": "爆發時以{v}蔓延至同排敵人",
    "터진 적에게 {v} 확률로 화상\tBurst enemies are Burned ({v} chance)": "有{v}機率使爆發的敵人燃燒",
    "지속 시간 증가\tLonger duration": "持續時間延長",
    "무는 간격 {v} 단축\tBites {v} faster": "撕咬間隔縮短{v}",
    "물 때마다 화염 저항 {v} 감소(최대 {a}겹)\tEach bite lowers Fire Resistance by {v} (up to {a} stacks)": "每次撕咬降低火焰抗性{v}（最多{a}層）",
    "같은 시간에 {v}방 더 긁는다\t{v} more ticks in the same time": "相同時間內多刮擦{v}次",
    "방마다 후열 무작위 하나에게 조각({v} · 결빙)\tEach tick a shard hits a random back-row enemy ({v} · Freeze)": "每次刮擦向一名隨機後排敵人射出碎片（{v} · 凍結）",
    "구름 속에서 틱마다 피해 {v}씩 증가\tDamage grows by {v} each tick inside the storm": "雪雲中傷害每跳遞增{v}",
    "구름 속 적이 받는 피해 {v} 증가\tEnemies in the storm take {v} more damage": "雪雲中的敵人受到的傷害提高{v}",
    "보호막 증가\tStronger shield": "護盾提高",
    "물리 피해도 {v} 막는다\tAlso absorbs {v} of physical damage": "也能抵擋{v}的物理傷害",
    "깨질 때 깬 적에게 냉기 {v}(결빙)\tWhen broken, deals {v} Cold to the breaker (Freeze)": "破碎時對擊破者造成冰霜傷害{v}（凍結）",
    "「한 번 더」 최대 +{v}\t\"Strike again\" cap +{v}": "“再落一道”上限+{v}",
    "맞은 적 {v} 확률로 {a}초 스턴\t{v} chance to Stun the enemy hit for {a}s": "有{v}機率使被擊中的敵人眩暈{a}秒",
    "쿨타임 감소\tShorter cooldown": "冷卻縮短",
    "쓸 때마다 다음 노바 {v} 세진다(최대 {a}겹 · 라운드마다 처음부터)\tEach cast makes the next Nova {v} stronger (up to {a} · resets each round)": "每次施放使下一次新星增強{v}（最多{a}層 · 每回合重新計算）",
    "맞은 적 번개 저항 {v} 감소(최대 {a}겹)\tLowers Lightning Resistance by {v} (up to {a} stacks)": "降低被擊中敵人的閃電抗性{v}（最多{a}層）",
    "벼락 데미지 증가\tMore bolt damage": "落雷傷害提高",
    "터질 때마다 남은 벼락 {v} 세진다\tEach burst makes the remaining bolts {v} stronger": "每次爆發使剩餘落雷增強{v}",
    "맞은 적의 스킬 쿨 {v}초 밀림\tPushes the target's skill cooldowns back {v}s": "被擊中敵人的技能冷卻推遲{v}秒",
    "데미지 · 공격 속도 증가\tMore Damage and Attack Speed": "傷害、攻擊速度提高",
    "창 동안 평타가 같은 줄 적에게 {v} 튄다\tDuring the window basic attacks splash the same row for {v}": "效果期間普攻以{v}濺射到同排敵人",
    "창 동안 받는 디버프 시간 {v} 감소\tDebuffs on you last {v} shorter during the window": "效果期間受到的減益時間縮短{v}",
    "다른 액티브 데미지 증가\tMore damage for other actives": "其他主動技能傷害提高",
    "HP가 낮을수록 피해 증가(최대 {v})\tMore damage the lower your HP (up to {v})": "生命越低傷害越高（最多{v}）",
    "쓰는 HP {v} 감소\tCosts {v} less HP": "消耗的生命降低{v}",
    "같은 적을 한 번 더 내려친다({v})\tStrikes the same enemy again ({v})": "再次劈砍同一敵人（{v}）",
    "맞은 적 {v}초 스턴\tStuns the enemy hit for {v}s": "使被擊中的敵人眩暈{v}秒",
