    "맞은 적 방어 {v} 깎기(최대 {a}겹)\tShreds {v} Defense per hit (up to {a} stacks)": "削減被擊中敵人的防禦{v}（最多{a}層）",
    "나머지 적이 받는 비율 +{v}\tOther enemies take +{v} of the blow": "其餘敵人承受的比例+{v}",
