    "앞으로 끌려나온 후열이 받는 물리 피해 {v} 증가\tPulled-forward back row takes {v} more physical damage": "被拉到前方的後排受到的物理傷害提高{v}",
    "최대 HP 증가\tMore max HP": "最大生命提高",
    "잃은 HP가 많을수록 재생 증가(최대 {v})\tRegeneration grows with missing HP (up to {v})": "損失的生命越多再生越高（最多{v}）",
    "창 동안 받는 경직 시간 {v} 감소\tStagger on you is {v} shorter during the window": "效果期間受到的僵直時間縮短{v}",
    "데미지 증가량 증가\tBigger Damage boost": "傷害增加量提高",
