    "데미지 감소량 증가\tBigger Damage reduction": "傷害降低量提高",
    "맞은 적 {v}초 경직\tStaggers enemies for {v}s": "使被擊中的敵人僵直{v}秒",
    "맞은 적이 거는 버프 시간 {v} 감소\tBuffs cast by enemies hit are {v} shorter": "被擊中敵人施加的增益時間縮短{v}",
    "가져온 피해 감소\tLess damage from what you take": "承擔的傷害降低",
    "아군 HP가 {v} 아래면 저절로 켜진다\tTurns on by itself when an ally drops below {v} HP": "友方生命低於{v}時自動開啟",
    "창 동안 쓰러지지 않는다 — 버틸 때 받는 피해 {v} 감소\tCannot fall during the window — {v} less damage while holding on": "效果期間不會倒下——撐住時受到的傷害降低{v}",
    "겹 하나의 피해 감소 증가\tMore reduction per stack": "每層傷害減擴音高",
    "창이 끝나면 겹이 {v}초마다 하나씩 빠진다\tAfter the window stacks fall off one every {v}s": "效果結束後每{v}秒移除1層",
    "겹이 가득 차면 파티에 겹의 {v}를 나눠 준다\tAt full stacks shares {v} of them with the party": "層數疊滿時將層數的{v}分給隊伍",
    "반사 증가\tMore reflection": "反射提高",
    "되돌린 피해의 {v}를 적 전원에게 나눠 준다\tSplits {v} of reflected damage across every enemy": "將反射傷害的{v}分攤給全體敵人",
    "창이 끝날 때 되돌린 양의 {v}가 적 전원에게 터진다\tWhen the window ends, bursts every enemy for {v} of the total reflected": "效果結束時，反射總量的{v}在全體敵人身上爆發",
    "상태이상 · 디버프 시간 감소 증가\tBigger duration cut": "異常狀態、減益時間縮短效果提高",
    "상태이상이 걸리는 순간 {v} 확률로 바로 풀린다\t{v} chance to shake off an Ailment instantly": "受到異常狀態時有{v}機率立即解除",
