    "세 수치 증가\tBigger bonuses": "三項數值提高",
    "마법 무기 아군 캐스팅 속도 +{v} 더\tMagic-weapon allies gain +{v} more Cast Speed": "持魔法武器的友方施法速度再+{v}",
    "물리 무기 아군 공격 속도 +{v} 더\tPhysical-weapon allies gain +{v} more Attack Speed": "持物理武器的友方攻擊速度再+{v}",
