    "바뀐 번개가 {v} 확률로 터진다(×{a})\tConverted lightning bursts ({v} chance · ×{a})": "轉化的閃電有{v}機率爆發（×{a}）",
    "창 동안 처치마다 창 +{v}초(최대 +{a}초)\tEach kill in the window extends it {v}s (up to +{a}s)": "效果期間每次擊殺，效果時間+{v}秒（最多+{a}秒）",
    "기본 피해 증가\tMore base damage": "基礎傷害提高",
    "쓰러뜨리면 남은 피해의 {v}가 다음 적에게\tOn a kill {v} of the leftover carries to the next enemy": "擊倒後剩餘傷害的{v}轉移到下一名敵人",
