    "화상 걸린 적이 쓰러지면 옆 적에게 화상이 옮는다\tBurn jumps to a neighbor when a Burned enemy falls": "燃燒中的敵人倒下時，燃燒轉移到相鄰敵人",
    "적 방어 100마다 전환 몫 +{v}\tConversion share +{v} per 100 enemy Defense": "敵人防禦每100點，轉化比例+{v}",
    "창을 열 때 적 전열 전원에게 번개 {v}\tOpening the window strikes the enemy front row with lightning for {v}": "效果開啟時對敵方前排全體造成閃電{v}",
    "터지면 옆 적에게 번개가 {v} 튄다\tBursts arc to a neighbor for {v}": "爆發時閃電以{v}濺射到相鄰敵人",
    "창 동안 처치마다 공속 +{v} 한 겹\tEach kill in the window adds a {v} Attack Speed stack": "效果期間每次擊殺獲得1層攻速+{v}",
    "잃은 체력 비례 몫 +{v}\tMissing-HP share +{v}": "按已損失生命計算的部分+{v}",
    "넘김이 두 번까지\tCarries over up to twice": "最多轉移兩次",
    "후열까지 고른다\tCan pick the back row too": "也可選擇後排",
    "내려꽂은 뒤 3초 동안 받는 피해 {v} 감소\tTake {v} less damage for 3s after landing": "落地後受到的傷害降低{v}，持續3秒",
    "튄 번개도 터질 수 있다\tThe arcs can burst too": "濺射的閃電也能爆發",
    "스턴이 안 걸리면 다음 낙하 검격의 스턴 확률 +{v}\tA miss raises the next Stun chance by {v}": "未造成眩暈時，下一次墜落斬的眩暈機率+{v}",
    "창을 열 때 스나이프가 바로 준비된다\tSnipe is ready the moment the window opens": "效果開啟時狙擊立即就緒",
    "느려짐 없음\tNo slow": "無減速",
    "후열 대상에게 추가 피해 {v}\t{v} bonus damage to back-row targets": "對後排目標額外傷害{v}",
    "쓰러뜨리면 쿨 {v}가 돌아온다\tA kill refunds {v} of the cooldown": "擊倒時返還{v}冷卻",
    "따라가는 한 발이 후열까지 고를 수 있다\tThe follow-up can pick the back row": "追加的一發也可選擇後排",
    "혼자 남은 적이면 두 배\tDouble damage on the last enemy": "只剩一名敵人時翻倍",
    "초기화될 때 모든 액티브의 쿨이 초기화된다\tResets every active's cooldown": "重置時所有主動技能的冷卻一併重置",
    "다음 두 방이 세진다\tThe next two hits are empowered": "接下來兩擊增強",
    "경직 시간 두 배\tDouble Stagger duration": "僵直時間翻倍",
    "창이 끝날 때 마지막 한 발이 {v}\tA final shot for {v} when the window ends": "效果結束時最後一發造成{v}",
    "후열에 맞은 화살 +{v}\tArrows hitting the back row +{v}": "命中後排的箭矢+{v}",
    "덤이 두 번 더\tOn-hit effects repeat twice": "附加效果再觸發兩次",
    "세 번째 평타마다 두 배\tEvery third basic attack deals double": "每第三次普攻傷害翻倍",
    "HP 최다 적에게 추가 피해 {v}\t{v} bonus damage to the highest-HP enemy": "對生命最多的敵人額外傷害{v}",
    "관통한 화살이 뒤 적을 {v}초 경직\tPierced arrows Stagger for {v}s": "貫穿的箭矢使後方敵人僵直{v}秒",
    "창 동안 쓰러진 적이 터져 같은 줄에 {v}\tEnemies killed in the window explode on their row for {v}": "效果期間倒下的敵人會爆炸，對同排造成{v}",
    "추가 대상의 덤이 주 대상과 같은 세기\tFull-strength on-hit effects on extra targets": "額外目標的附加效果與主目標強度相同",
    "연속 평타는 관통 비율이 줄지 않는다\tChained shots keep the full chain share": "連續普攻的貫穿比例不會降低",
    "표식 적이 받은 피해의 {v}가 적 전원에게 번진다\t{v} of damage to the marked enemy spreads to every enemy": "被標記的敵人所受傷害的{v}蔓延到全體敵人",
