    "가산 상한 +{v}\tBonus cap +{v}": "加成上限+{v}",
    "지운 것 하나당 터짐 두 배\tDoubles the burst per consumed debuff": "每個被清除效果的引爆翻倍",
    "저주받은 적이 쓰러지면 파티 전원 최대 HP {v} 회복\tWhen the cursed enemy falls, heals the party for {v} of max HP": "被詛咒的敵人倒下時，隊伍全員恢復最大生命的{v}",
    "전원 저주의 회복이 가장 다친 아군에게 몰린다\tAll-enemy healing goes to the most wounded ally": "全體詛咒的治療集中於傷勢最重的友方",
    "벗긴 버프를 아군에게 옮겨 온다\tStolen buffs go to your allies": "剝除的增益轉移給友方",
