    "불길을 피해 마을 사람들이 숨던 굴입니다\n두고 간 짐과 무기가 아직 그대로 쌓여 있습니다\tVillagers hid here from the fires\nThe packs and weapons they left are still piled inside": "村民們曾躲進這處洞穴避開大火\n他們丟下的行囊與兵器仍原樣堆在裡面",
    "전쟁의 첫 화염이 오른 봉화대입니다\n그을린 돌벽에 옛 군령이 아직 새겨져 있습니다\tThe beacon where the war's first fire was lit\nOld orders are still carved into the scorched stone": "戰爭的第一把火就在這座烽火臺上燃起\n燻黑的石牆上仍刻著昔日的軍令",
    "불탄 들을 가로질러 곡식을 나릅니다\n굶주린 자들은 적이든 아군이든 수레부터 노립니다\tHauls grain across the burnt fields\nThe starving of both sides go for the wagons first": "穿過焚燬的田野運送糧食\n飢餓的人不分敵我，最先盯上的總是糧車",
    "까마귀들이 남의 것을 물어다 쌓는 굴입니다\n반짝이기만 하면 칼날이든 반지든 가리지 않습니다\tCrows hoard what belongs to others here\nAny blade or ring that glints will do": "烏鴉把別人的東西銜來，堆在這處洞穴裡\n只要會發亮，刀刃也好，戒指也好，一概不挑",
    "우상족이 깎은 나무 가면이 줄지어 걸려 있습니다\n가면마다 다른 누군가의 얼굴을 흉내 냅니다\tRows of wooden masks carved by the Idolfolk\nEach one copies someone else's face": "偶像族雕刻的木面具一排排掛在這裡\n每一張都在模仿另一個人的臉",
    "안개 낀 늪 사이로 모피를 실어 나릅니다\n나무들이 서로를 향해 굽어 길이 날마다 바뀝니다\tCarries furs through the misty marsh\nThe trees bend toward one another and the road shifts daily": "穿過霧氣瀰漫的沼澤運送毛皮\n樹木彼此相向彎曲，道路每天都在變",
    "도굴꾼들이 무덤에서 파낸 것을 숨겨 두는 굴입니다\n찾으러 돌아온 주인은 아무도 없습니다\tGrave robbers stash their spoils here\nNot one of them ever came back to claim it": "盜墓賊把從墳墓裡挖出的東西藏在這處洞穴\n從來沒有哪個主人回來取過",
    "모든 길손에게 통행세를 걷던 세관입니다\n무너진 벽 아래에서 장부가 아직 빚을 셉니다\tA customs house that taxed every traveler\nUnder the fallen walls the ledgers still count debts": "這座稅關曾向每一個過客徵收通行稅\n坍塌的牆下，賬簿仍在清算欠債",
    "향신료를 실은 낙타가 줄지어 갑니다\n삯을 올려 부르는 상단 주인이 도적보다 무섭습니다\tA line of camels laden with spice\nThe master who keeps raising the fee is worse than bandits": "滿載香料的駱駝排成長隊前行\n不斷抬高運費的商隊主人比盜賊還可怕",
    "길 잃은 원정대가 잠시 쉬어 가던 굴입니다\n내려놓은 짐과 무기 곁에서 그대로 얼어붙었습니다\tA lost expedition stopped here for a short rest\nThey froze beside the packs and weapons they set down": "迷路的遠征隊曾在這處洞穴稍作歇息\n他們就那樣凍僵在放下的行囊與兵器旁",
    "눈에 묻힌 수도원입니다\n필사하던 수도사들이 펜을 쥔 채 얼어 있습니다\tA monastery buried in snow\nThe scribes froze with their pens still in hand": "這是一座埋在雪中的修道院\n正在抄寫的修士們手握著筆凍在原處",
    "개 썰매가 얼음 위로 소금을 끕니다\n잠깐 쉬어 가자는 말이 나오면 그 자리에 멈춥니다\tDog sleds haul salt across the ice\nWhoever suggests a short rest stops there for good": "狗拉雪橇在冰面上拖運鹽貨\n只要有人說歇一歇，便在原地停下",
    "삼킨 것을 끝내 다 소화하지 못한 굴입니다\n벽 틈마다 씹다 만 갑옷과 칼이 박혀 있습니다\tThe cave never finished digesting what it swallowed\nHalf-chewed armor and blades jut from every crack": "這處洞穴吞下的東西始終沒能消化乾淨\n每道巖縫裡都嵌著嚼了一半的盔甲與刀劍",
    "땅이 꺼지며 통째로 삼켜진 마을입니다\n식탁에는 차려 둔 음식이 아직 굳어 있습니다\tA village swallowed whole when the ground gave way\nThe meals set out still harden on the tables": "大地塌陷時，這座村莊被整個吞了下去\n桌上擺好的飯菜至今仍凝結著",
    "동굴 마을로 식량을 실어 나릅니다\n도착할 때마다 실은 것보다 먹어 치운 것이 많습니다\tHauls provisions to the cave towns\nMore gets eaten on the way than ever arrives": "向洞穴裡的村落運送糧食\n每次抵達時，吃掉的都比裝上車的多",
    "궁전의 포도주를 익히던 굴입니다\n취해 잠든 손님들의 장신구가 바닥에 흩어져 있습니다\tWhere the palace aged its wine\nJewelry of guests who drank themselves to sleep lies scattered": "宮殿曾在這處洞穴裡窖藏葡萄酒\n醉倒酣睡的賓客們的首飾散落一地",
    "춤이 멈추지 않던 무도회장입니다\n깨진 거울마다 다른 누군가가 춤을 춥니다\tA ballroom where the dancing never stopped\nSomeone else dances in every broken mirror": "這座舞廳裡的舞從未停歇\n每一面碎鏡中都有另一個人在跳舞",
    "궁전에 바칠 비단과 향을 싣고 갑니다\n짐을 지키던 호위가 하나둘 궁전 쪽으로 사라집니다\tCarries silk and incense meant for the palace\nOne by one the guards drift off toward it": "載著要獻給宮殿的絲綢與薰香前行\n看守貨物的護衛一個接一個朝宮殿那邊消失了",
    "산을 오르던 순례자들이 쉬어 가던 굴입니다\n자격이 없다며 두고 간 칼과 방패가 쌓여 있습니다\tPilgrims rested here on the climb\nSwords and shields lie where the unworthy laid them down": "登山的朝聖者曾在這處洞穴歇腳\n自稱不配的人留下的劍與盾堆在這裡",
    "하늘에 닿으려고 쌓던 탑입니다\n무너질 때마다 더 높은 돌에 새 이름이 새겨졌습니다\tA tower raised to reach the sky\nEach collapse left new names carved on higher stones": "這是為了觸及天空而堆砌的高塔\n每次倒塌，新的名字便刻上更高處的石塊",
    "산꼭대기 신전으로 성물을 실어 올립니다\n짐보다 무거운 것은 주인의 이름값입니다\tHauls holy relics up to the summit temple\nHeavier than the cargo is the owner's reputation": "把聖物運上山頂的神殿\n比貨物更沉重的，是主人的名聲",
