    "총합이 낮은 대역 · 분포가 넓어 한 축이 크게 튈 수 있음\tLower stat total · a wide spread so one axis can spike": "總和較低的區間 · 分佈較廣，可能在某一軸上大幅突出",
    "총합이 높은 대역 · 정규분포라 극값이 드물고 고르게 분포\tHigher stat total · a normal spread so extremes are rare": "總和較高的區間 · 呈正態分佈，極端值少見，分佈均勻",
    "이름·직업·죄종 고정 + 고유 스킬 1개(영웅 전용) · 영웅 로스터에 1명만\tFixed name class & sin + 1 signature skill (hero-exclusive) · one per roster": "名稱、職業、罪宗固定 + 1個固有技能（英雄專屬） · 英雄名冊中僅限1名",
    "총합이 가장 낮은 대역 · 정규분포라 고르게 분포\tLowest stat total · a normal spread so stats come out even": "總和最低的區間 · 呈正態分佈，分佈均勻",
    "고블린 전용 등급 · 모든 능력치가 낮게 시작 · 레벨마다 능력치 하나 성장\tGoblin-only grade · every stat starts low · one stat grows each level": "哥布林專屬稀有度 · 所有屬性起點較低 · 每級成長一項屬性",
