    "롱 보우\tLong Bow": "長弓",
    "숏 배틀 보우\tShort Battle Bow": "短戰弓",
    "레이저 보우\tRazor Bow": "刀鋒弓",
    "롱 배틀 보우\tLong Battle Bow": "長戰弓",
    "다이아몬드 보우\tDiamond Bow": "鑽石弓",
    "블레이드 보우\tBlade Bow": "利刃弓",
    "하이드라 보우\tHydra Bow": "九頭蛇弓",
